// SCRAM example program: registers a user, authenticates it, then shows
// what happens when the password is wrong and when the server cannot
// prove itself.
//
// Run with:  v run examples/scram.v
import crypto.scram

// A stand-in for the table a real server would keep. SCRAM never stores
// the password, only the salt, the iteration count and two derived keys.
struct UserStore {
mut:
	records map[string]scram.Credentials
}

fn (mut s UserStore) register(username string, password string) ! {
	s.records[username] = scram.new_credentials(.sha256, password)!
}

fn main() {
	mut store := UserStore{}
	store.register('alice', 'correct horse battery staple')!
	println('registered alice: stored ${store.records['alice'].stored_key.len} byte keys, no password')

	demo_successful_login(store)!
	demo_wrong_password(store)!
	demo_impostor_server(store)!
}

// The nominal exchange. In a real program the two halves sit on either
// side of a socket and only the four strings travel.
fn demo_successful_login(store UserStore) ! {
	println('\n--- a successful login ---')
	mut server := new_server_for(store)!
	mut client := scram.new_client(username: 'alice', password: 'correct horse battery staple')!

	client_first := client.first()!
	println('C: ${client_first}')
	server_first := server.first(client_first)!
	println('S: ${server_first}')
	client_final := client.final(server_first)!
	println('C: ${client_final}')
	server_final := server.final(client_final)!
	println('S: ${server_final}')

	// Only now is the connection authenticated, in both directions.
	client.verify(server_final)!
	println('=> ${server.username()} is authenticated, and the server proved itself too')
}

// A wrong password produces a well formed exchange that fails on the
// proof. The server answers with an `e=` code rather than hanging up, so
// the client can tell a refusal from a broken connection.
fn demo_wrong_password(store UserStore) ! {
	println('\n--- a wrong password ---')
	mut server := new_server_for(store)!
	mut client := scram.new_client(username: 'alice', password: 'hunter2')!

	server_first := server.first(client.first()!)!
	refusal := server.final(client.final(server_first)!) or {
		println('server: ${err}')
		scram.server_error_message('invalid-proof')
	}
	client.verify(refusal) or {
		println('client: ${err}')
		if err is scram.ServerError {
			println('=> the server refused with the code `${err.code}`')
		}
		return
	}
	println('=> unreachable: a wrong password was accepted')
}

// The step everyone is tempted to skip. A server that does not hold the
// credentials can still answer the first three messages; it cannot sign
// the fourth. Dropping `verify` turns SCRAM into a one-way protocol and
// throws away its protection against a relay.
fn demo_impostor_server(store UserStore) ! {
	println('\n--- a server that cannot prove itself ---')
	mut server := new_server_for(store)!
	mut client := scram.new_client(username: 'alice', password: 'correct horse battery staple')!

	server_first := server.first(client.first()!)!
	server.final(client.final(server_first)!)!
	// Everything above succeeded; the impostor now has to sign the
	// transcript, and forges the signature instead.
	forged := 'v=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA='
	client.verify(forged) or {
		println('client: ${err}')
		println('=> the client refused the server, and never revealed the password')
		return
	}
	println('=> unreachable: a forged server signature was accepted')
}

// new_server_for wires a server to the user store. Returning an error
// for an unknown user is the simple choice made here; a public facing
// server should answer with credentials derived from a server-side
// secret instead, so that probing for user names tells an attacker
// nothing. See RFC 5802 section 7.
fn new_server_for(store UserStore) !&scram.Server {
	return scram.new_server(
		mechanism: .sha256
		lookup:    fn [store] (username string) !scram.Credentials {
			return store.records[username] or { error('unknown user: ${username}') }
		}
	)
}

module main

import veb

@['/controller/auth'; post]
pub fn (mut app App) controller_auth(mut ctx Context, username string, password string) veb.Result {
	response := app.service_auth(username, password) or {
		ctx.res.set_status(.bad_request)
		return ctx.text('error: ${err}')
	}

	return ctx.json(response)
}

PicoHTTPParser
=============

Copyright (c) 2009-2014 [Kazuho Oku](https://github.com/kazuho), [Tokuhiro Matsuno](https://github.com/tokuhirom), [Daisuke Murase](https://github.com/typester), [Shigeo Mitsunari](https://github.com/herumi)

PicoHTTPParser is a tiny, primitive, fast HTTP request/response parser.

Unlike most parsers, it is stateless and does not allocate memory by itself.
All it does is accept pointer to buffer and the output structure, and setups the pointers in the latter to point at the necessary portions of the buffer.

The code is widely deployed within Perl applications through popular modules that use it, including [Plack](https://metacpan.org/pod/Plack), [Starman](https://metacpan.org/pod/Starman), [Starlet](https://metacpan.org/pod/Starlet), [Furl](https://metacpan.org/pod/Furl).  It is also the HTTP/1 parser of [H2O](https://github.com/h2o/h2o).

Check out [test.c] to find out how to use the parser.

The software is dual-licensed under the Perl License or the MIT License.

Usage
-----

The library exposes four functions: `phr_parse_request`, `phr_parse_response`, `phr_parse_headers`, `phr_decode_chunked`.

### phr_parse_request

The example below reads an HTTP request from socket `sock` using `read(2)`, parses it using `phr_parse_request`, and prints the details.

```c
char buf[4096], *method, *path;
int pret, minor_version;
struct phr_header headers[100];
size_t buflen = 0, prevbuflen = 0, method_len, path_len, num_headers;
ssize_t rret;

while (1) {
    /* read the request */
    while ((rret = read(sock, buf + buflen, sizeof(buf) - buflen)) == -1 && errno == EINTR)
        ;
    if (rret <= 0)
        return IOError;
    prevbuflen = buflen;
    buflen += rret;
    /* parse the request */
    num_headers = sizeof(headers) / sizeof(headers[0]);
    pret = phr_parse_request(buf, buflen, &method, &method_len, &path, &path_len,
                             &minor_version, headers, &num_headers, prevbuflen);
    if (pret > 0)
        break; /* successfully parsed the request */
    else if (pret == -1)
        return ParseError;
    /* request is incomplete, continue the loop */
    assert(pret == -2);
    if (buflen == sizeof(buf))
        return RequestIsTooLongError;
}

printf("request is %d bytes long\n", pret);
printf("method is %.*s\n", (int)method_len, method);
printf("path is %.*s\n", (int)path_len, path);
printf("HTTP version is 1.%d\n", minor_version);
printf("headers:\n");
for (i = 0; i != num_headers; ++i) {
    printf("%.*s: %.*s\n", (int)headers[i].name_len, headers[i].name,
           (int)headers[i].value_len, headers[i].value);
}
```

### phr_parse_response, phr_parse_headers

`phr_parse_response` and `phr_parse_headers` provide similar interfaces as `phr_parse_request`.  `phr_parse_response` parses an HTTP response, and `phr_parse_headers` parses the headers only.

### phr_decode_chunked

The example below decodes incoming data in chunked-encoding.  The data is decoded in-place.

```c
struct phr_chunked_decoder decoder = {}; /* zero-clear */
char *buf = malloc(4096);
size_t size = 0, capacity = 4096, rsize;
ssize_t rret, pret;

/* set consume_trailer to 1 to discard the trailing header, or the application
 * should call phr_parse_headers to parse the trailing header */
decoder.consume_trailer = 1;

do {
    /* expand the buffer if necessary */
    if (size == capacity) {
        capacity *= 2;
        buf = realloc(buf, capacity);
        assert(buf != NULL);
    }
    /* read */
    while ((rret = read(sock, buf + size, capacity - size)) == -1 && errno == EINTR)
        ;
    if (rret <= 0)
        return IOError;
    /* decode */
    rsize = rret;
    pret = phr_decode_chunked(&decoder, buf + size, &rsize);
    if (pret == -1)
        return ParseError;
    size += rsize;
} while (pret == -2);

/* successfully decoded the chunked data */
assert(pret >= 0);
printf("decoded data is at %p (%zu bytes)\n", buf, size);
```

Benchmark
---------

![benchmark results](http://i.gyazo.com/a85c18d3162dfb46b485bb41e0ad443a.png)

The benchmark code is from [fukamachi/fast-http@6b91103](https://github.com/fukamachi/fast-http/tree/6b9110347c7a3407310c08979aefd65078518478).

The internals of picohttpparser has been described to some extent in [my blog entry]( http://blog.kazuhooku.com/2014/11/the-internals-h2o-or-how-to-write-fast.html).

// vtest build: present_openssl? && !(openbsd && gcc) && !(sanitize-memory-clang || docker-ubuntu-musl)
// vtest vflags: -d use_openssl
import rand
import crypto.ecdsa
import encoding.hex

// The test file placed on its own directory. Its for workaround for
// module lookup problem, because there are two rand module availables,
// between `crypto.rand` and `rand` module.
// See [the talk](https://discord.com/channels/592103645835821068/592294828432424960/1328198034806407311) on discord.

fn test_new_key_from_seed_with_random_size_and_data() ! {
	num_iters := 100
	// default prime256v1 curve key size was 32 bytes.
	max_key_size := i32(48)
	for i := 0; i <= num_iters; i++ {
		m := rand.i32n(max_key_size)!
		random_bytes := rand.bytes(m)!
		pvkey := ecdsa.new_key_from_seed(random_bytes) or {
			// With default size, would error on m > 32 or m == 0
			// dump(m)
			if m == 0 {
				assert err == error('Seed with null-length was not allowed')
			} else if m > 32 {
				assert err == error('Seed length exceeds key size')
			} else {
				assert err == error('EC_KEY_check_key failed')
			}
			continue
		}
		ret_seed := pvkey.bytes()!
		assert random_bytes == ret_seed
		pvkey.free()
	}
}

fn test_private_and_public_key_from_string() ! {
	// See [this](https://github.com/vlang/v/blob/master/vlib/crypto/ecdsa/util_test.v) for detail
	// of material used as a sample.
	privkey_sample := '-----BEGIN PRIVATE KEY-----
MIG2AgEAMBAGByqGSM49AgEGBSuBBAAiBIGeMIGbAgEBBDAwzj2iiJZaxgk/C6mp
oVskdr6j7akl4bPB8JRnT1J5XNbLPK/iNd/BW+xUJEj/pxWhZANiAAT4/euEWRPV
9cdhtjcKlwF2HrFMLvgxAXFx+01UPfMQ9XOj/85qUhVq1jXraSyDy5FYF28UW4dn
04xVeRuPBbCFxc/uqYj2s5ItHcAZSV3L5sGlXadPfTqoIjCBQAx44k8=
-----END PRIVATE KEY-----'

	pubkey_sample := '-----BEGIN PUBLIC KEY-----
MHYwEAYHKoZIzj0CAQYFK4EEACIDYgAE+P3rhFkT1fXHYbY3CpcBdh6xTC74MQFx
cftNVD3zEPVzo//OalIVatY162ksg8uRWBdvFFuHZ9OMVXkbjwWwhcXP7qmI9rOS
LR3AGUldy+bBpV2nT306qCIwgUAMeOJP
-----END PUBLIC KEY-----'

	// Message tobe signed and verified
	message_tobe_signed := 'Example of ECDSA with P-384'.bytes()
	// Message signature generated with SHA384 digest with associated key previously.
	signature :=
		hex.decode('3066023100b08f6ec77bb319fdb7bce55a2714d7e79cc645d834ee539d8903cfcc88c6fa90df1558856cb840b2dd82e82cd89d7046023100d9d482ca8a6545a3b081fbdd4bb9643a2b4eda4e21fd624833216596032471faae646891f8d2f0bbb86b796c36d3c390')!

	// loads a Privatekey and PublicKey from above sample
	privkey := ecdsa.privkey_from_string(privkey_sample)!
	pubkey := ecdsa.pubkey_from_string(pubkey_sample)!
	// get a public key from private key
	pbkey_from_privkey := privkey.public_key()!

	// two public key should be equal, its comes from the same source.
	assert pubkey.equal(pbkey_from_privkey)

	// lets create the signature
	created_signature := privkey.sign(message_tobe_signed)!

	verified1 := pubkey.verify(message_tobe_signed, signature)!
	verified2 := pubkey.verify(message_tobe_signed, created_signature)!

	assert verified1 == true
	assert verified2 == true

	// Its also should be verified with pbkey_from_privkey opaque
	verified3 := pbkey_from_privkey.verify(message_tobe_signed, signature)!
	verified4 := pbkey_from_privkey.verify(message_tobe_signed, created_signature)!
	assert verified3 == true
	assert verified4 == true

	// release the key
	privkey.free()
	pubkey.free()
	pbkey_from_privkey.free()
}

# mcp integration tests

These tests keep MCP traffic in memory. They do not start stdio, HTTP, a child
process, or any external MCP service.

The coverage target is the `x.async` boundary around MCP-shaped work:

- build an MCP request;
- decode and validate it inside a `Task`;
- produce an MCP response;
- decode the result after `Task.wait()`.

module main

import x.atomics

fn increment(counter &i64) {
	atomics.add_i64(counter, 1)
}

fn worker(counter &i64, iterations int) {
	for _ in 0 .. iterations {
		increment(counter)
	}
}

fn main() {
	mut counter := i64(0)

	num_threads := 4
	increments_per_thread := 10000

	mut threads := []thread{}

	for _ in 0 .. num_threads {
		threads << spawn worker(&counter, increments_per_thread)
	}

	threads.wait()

	expected := i64(num_threads * increments_per_thread)
	actual := atomics.load_i64(&counter)

	println('Expected: ${expected}')
	println('Actual:   ${actual}')

	if actual == expected {
		println('Counter is correct')
	} else {
		println('Counter mismatch - race condition detected')
	}
}

# Adding Providers to the Local Tunnel Debugger

The Local Tunnel Debugger is intended to provide a local debugging option that includes
the benefits of remote debugging. Traffic from the cluster is rerouted to the version of the application 
running locally, so that developers can run and debug their code while freely communicating
with resources in the cluster.

Local Tunnel Debug providers can be installed via the marketplace. Developers of extensions with 
tunnel debugging capabilities can register themselves as a Local Tunnel Debug provider in order
to hook into the Kubernetes extension's API.

## Elements of a debug provider

An object that provides content for the Local Tunnel Debugger is called a _local tunnel debug provider_.
Providers must be hosted within a Visual Studio Code extension.  This table summarises what
your providers and their hosting extension need to do; the rest of this article goes into detail.

| Component            | Responsibilities                                                     |
|----------------------|----------------------------------------------------------------------|
| Your extension       | <ul><li>Activate when the Cluster Explorer is displayed or when the Debug (Local Tunnel) option is selected in the command palette</li><li>Register debug providers with Kubernetes extension</li><li>Tag itself as a local tunnel debug provider in the Visual Studio Marketplace</li></ul>        |
| Local Tunnel Debug Provider| <ul><li>Implement the local tunnel debug provider interface</li><li>Resolve the command target</li><li>Gather choices from the user in order to generate or select the debug configuration to use</li><li>Start a Local Tunnel debugging session in response to the Debug (Local Tunnel) command</li></ul>  |
| Kubernetes extension | <ul><li>Display the Debug (Local Tunnel) command in the palette or when interacting with supported resources in the Cluster Explorer</li><li>Allow users to configure which debug provider to use</li></ul>                               |                              |

## Implementing the local tunnel debug provider

A local tunnel debug provider must implement the following interface.  (For documentation purposes
the interface is written in TypeScript terms but any JavaScript object that provides
the specified properties and methods will do.)

```javascript
interface LocalTunnelDebugProvider {
    readonly id: string;
    startLocalTunnelDebugging(target?: any): void;
}
```

### Implementing the metadata

The `id` should be a user-friendly name for your debug provider, such as `Contoso Trampoline Debugger`.  
The `id` will allow users to configure a default local tunnel debugger to use by setting the `vs-kubernetes.local-tunnel-debug-provider` field under `vs-kubernetes` in settings.json.

### Implementing the debugger

Your provider's implementation of `startLocalTunnelDebugging(target?: any)` is responsible for resolving the debug target (such as a pod or service) and starting the debug session. You can use the cluster explorer API to resolve the target (see [commandtargets.md](commandtargets.md) for more info).

Currently, Debug (Local Tunnel) is offered on services, deployments, pods and jobs. A provider is expected to handle debugging
on these types.

An example implementation is given below:

```javascript
const MY_PROVIDER = {
    id: "Contoso Trampoline Debugger",
    startLocalTunnelDebugging: (target?: any) => startDebugSession(target)
};

function startDebugSession(target?: any) {
    const clusterExplorer = await k8s.extension.clusterExplorer.v1;
    const commandTarget = clusterExplorer.resolveCommandTarget(target);

    if (commandTarget) {
        if (commandTarget.nodeType === 'resource') {
            if (commandTarget.resourceKind.manifestKind === 'Pod') {

                // Custom logic for selecting or generating the Local Tunnel debug configuration goes here
                const configToUse: string | vscode.DebugConfiguration = this.resolveLocalTunnelDebugConfigurationForPod(commandTarget);

                // Start the debug session
                vscode.debug.startDebugging(folder, configToUse);
            }
        }
    } else {
        // The user selected the Debug (Local Tunnel) command from the command palette or from
        // somewhere else that you were displaying it.
    }
}
```

## Registering the debug provider

In order to hook into the Debug (Local Tunnel) option, a local debug provider must be _registered_
with the Kubernetes extension. This is the responsibility of the VS Code extension that hosts
the debug provider. To do this, the extension must:

* Activate in response to the `Debug (Local Tunnel)` command
* Request the Kubernetes extension's Local Tunnel Debug Provider API
* Call the `register` method for each debug provider it wants to display

Activating in response to the `kubernetes.clusterExplorer` view may give a better performance the first
time the command is selected, but is not required.

### Activating the debug provider extension

Your extension needs to activate in response to the Debug (Local Tunnel) command when
called from the cluster explorer or the command palette, so that it can register as a
debug provider before the debug session is started. To do this, your `package.json` must
include the following activation event:

```json
    "activationEvents": [
        "onCommand:extension.vsKubernetesDebugLocalTunnel",
    ],
```
To optionally activate in response to the cluster explorer view, you may use
the `onView:extension.vsKubernetesExplorer` event. Depending on your extension you
may have other activation events as well.

### Registering local tunnel debug providers with the Kubernetes extension

In your extension's `activate` function, you must register your provider(s) using the
Kubernetes extension API.  The following sample shows how to do this using the NPM
helper package; if you don't use the helper then the process of requesting the API is
more manual but the registration is the same.

```javascript
const MY_PROVIDER = {
    id: "Contoso Trampoline Debugger",
    startLocalTunnelDebugging: (target?: any) => startDebugSession(target)
};

export async function activate(context: vscode.ExtensionContext) {
    const localTunnelDebugger = await k8s.extension.localTunnelDebugger.v1;

    if (!localTunnelDebugger.available) {
        console.log("Unable to register provider: " + localTunnelDebugger.reason);
        return;
    }

    localTunnelDebugger.api.registerLocalTunnelDebugProvider(MY_PROVIDER);
}
```

Your debug provider is now ready for testing!

## Tagging your debug provider extension

The Local Tunnel Debugger has a link for users to find providers on the Visual Studio
Marketplace.  If you'd like to appear in this link, please tag your extension
with the keyword `kubernetes-extension-local-tunnel-debug-provider` in `package.json`.
For example:

```json
{
    "keywords": [
        "kubernetes",
        "contoso",
        "megafloof",
        "kubernetes-extension-local-tunnel-debug-provider"
    ]
}
```

# Reactivity API: Advanced {#reactivity-api-advanced}

## shallowRef() {#shallowref}

Shallow version of [`ref()`](./reactivity-core#ref).

- **Type**

  ```ts
  function shallowRef<T>(value: T): ShallowRef<T>

  interface ShallowRef<T> {
    value: T
  }
  ```

- **Details**

  Unlike `ref()`, the inner value of a shallow ref is stored and exposed as-is, and will not be made deeply reactive. Only the `.value` access is reactive.

  `shallowRef()` is typically used for performance optimizations of large data structures, or integration with external state management systems.

- **Example**

  ```js
  const state = shallowRef({ count: 1 })

  // does NOT trigger change
  state.value.count = 2

  // does trigger change
  state.value = { count: 2 }
  ```

- **See also**
  - [Guide - Reduce Reactivity Overhead for Large Immutable Structures](/guide/best-practices/performance#reduce-reactivity-overhead-for-large-immutable-structures)
  - [Guide - Integration with External State Systems](/guide/extras/reactivity-in-depth#integration-with-external-state-systems)

## triggerRef() {#triggerref}

Force trigger effects that depend on a [shallow ref](#shallowref). This is typically used after making deep mutations to the inner value of a shallow ref.

- **Type**

  ```ts
  function triggerRef(ref: ShallowRef): void
  ```

- **Example**

  ```js
  const shallow = shallowRef({
    greet: 'Hello, world'
  })

  // Logs "Hello, world" once for the first run-through
  watchEffect(() => {
    console.log(shallow.value.greet)
  })

  // This won't trigger the effect because the ref is shallow
  shallow.value.greet = 'Hello, universe'

  // Logs "Hello, universe"
  triggerRef(shallow)
  ```

## customRef() {#customref}

Creates a customized ref with explicit control over its dependency tracking and updates triggering.

- **Type**

  ```ts
  function customRef<T>(factory: CustomRefFactory<T>): Ref<T>

  type CustomRefFactory<T> = (
    track: () => void,
    trigger: () => void
  ) => {
    get: () => T
    set: (value: T) => void
  }
  ```

- **Details**

  `customRef()` expects a factory function, which receives `track` and `trigger` functions as arguments and should return an object with `get` and `set` methods.

  In general, `track()` should be called inside `get()`, and `trigger()` should be called inside `set()`. However, you have full control over when they should be called, or whether they should be called at all.

- **Example**

  Creating a debounced ref that only updates the value after a certain timeout after the latest set call:

  ```js
  import { customRef } from 'vue'

  export function useDebouncedRef(value, delay = 200) {
    let timeout
    return customRef((track, trigger) => {
      return {
        get() {
          track()
          return value
        },
        set(newValue) {
          clearTimeout(timeout)
          timeout = setTimeout(() => {
            value = newValue
            trigger()
          }, delay)
        }
      }
    })
  }
  ```

  Usage in component:

  ```vue
  <script setup>
  import { useDebouncedRef } from './debouncedRef'
  const text = useDebouncedRef('hello')
  </script>

  <template>
    <input v-model="text" />
  </template>
  ```

  [Try it in the Playground](https://play.vuejs.org/#)

  :::warning Use with caution
  When using customRef, we should be cautious about the return value of its getter, particularly when generating new object datatypes each time the getter is run. This affects the relationship between parent and child components, where such a customRef has been passed as a prop.

  The parent component's render function could be triggered by changes to a different reactive state. During rerender, the value of our customRef is reevaluated, returning a new object datatype as a prop to a child component. This prop is compared with its last value in the child component, and since they are different, the reactive dependencies of the customRef are triggered in the child component. Meanwhile, the reactive dependencies in the parent component do not run because the customRef's setter was not called, and its dependencies were not triggered as a result.

  [See it in the Playground](https://play.vuejs.org/#)

  :::

## shallowReactive() {#shallowreactive}

Shallow version of [`reactive()`](./reactivity-core#reactive).

- **Type**

  ```ts
  function shallowReactive<T extends object>(target: T): T
  ```

- **Details**

  Unlike `reactive()`, there is no deep conversion: only root-level properties are reactive for a shallow reactive object. Property values are stored and exposed as-is - this also means properties with ref values will **not** be automatically unwrapped.

  :::warning Use with Caution
  Shallow data structures should only be used for root level state in a component. Avoid nesting it inside a deep reactive object as it creates a tree with inconsistent reactivity behavior which can be difficult to understand and debug.
  :::

- **Example**

  ```js
  const state = shallowReactive({
    foo: 1,
    nested: {
      bar: 2
    }
  })

  // mutating state's own properties is reactive
  state.foo++

  // ...but does not convert nested objects
  isReactive(state.nested) // false

  // NOT reactive
  state.nested.bar++
  ```

## shallowReadonly() {#shallowreadonly}

Shallow version of [`readonly()`](./reactivity-core#readonly).

- **Type**

  ```ts
  function shallowReadonly<T extends object>(target: T): Readonly<T>
  ```

- **Details**

  Unlike `readonly()`, there is no deep conversion: only root-level properties are made readonly. Property values are stored and exposed as-is - this also means properties with ref values will **not** be automatically unwrapped.

  :::warning Use with Caution
  Shallow data structures should only be used for root level state in a component. Avoid nesting it inside a deep reactive object as it creates a tree with inconsistent reactivity behavior which can be difficult to understand and debug.
  :::

- **Example**

  ```js
  const state = shallowReadonly({
    foo: 1,
    nested: {
      bar: 2
    }
  })

  // mutating state's own properties will fail
  state.foo++

  // ...but works on nested objects
  isReadonly(state.nested) // false

  // works
  state.nested.bar++
  ```

## toRaw() {#toraw}

Returns the raw, original object of a Vue-created proxy.

- **Type**

  ```ts
  function toRaw<T>(proxy: T): T
  ```

- **Details**

  `toRaw()` can return the original object from proxies created by [`reactive()`](./reactivity-core#reactive), [`readonly()`](./reactivity-core#readonly), [`shallowReactive()`](#shallowreactive) or [`shallowReadonly()`](#shallowreadonly).

  This is an escape hatch that can be used to temporarily read without incurring proxy access / tracking overhead or write without triggering changes. It is **not** recommended to hold a persistent reference to the original object. Use with caution.

- **Example**

  ```js
  const foo = {}
  const reactiveFoo = reactive(foo)

  console.log(toRaw(reactiveFoo) === foo) // true
  ```

## markRaw() {#markraw}

Marks an object so that it will never be converted to a proxy. Returns the object itself.

- **Type**

  ```ts
  function markRaw<T extends object>(value: T): T
  ```

- **Example**

  ```js
  const foo = markRaw({})
  console.log(isReactive(reactive(foo))) // false

  // also works when nested inside other reactive objects
  const bar = reactive({ foo })
  console.log(isReactive(bar.foo)) // false
  ```

  :::warning Use with Caution
  `markRaw()` and shallow APIs such as `shallowReactive()` allow you to selectively opt-out of the default deep reactive/readonly conversion and embed raw, non-proxied objects in your state graph. They can be used for various reasons:

  - Some values simply should not be made reactive, for example a complex 3rd party class instance, or a Vue component object.

  - Skipping proxy conversion can provide performance improvements when rendering large lists with immutable data sources.

  They are considered advanced because the raw opt-out is only at the root level, so if you set a nested, non-marked raw object into a reactive object and then access it again, you get the proxied version back. This can lead to **identity hazards** - i.e. performing an operation that relies on object identity but using both the raw and the proxied version of the same object:

  ```js
  const foo = markRaw({
    nested: {}
  })

  const bar = reactive({
    // although `foo` is marked as raw, foo.nested is not.
    nested: foo.nested
  })

  console.log(foo.nested === bar.nested) // false
  ```

  Identity hazards are in general rare. However, to properly utilize these APIs while safely avoiding identity hazards requires a solid understanding of how the reactivity system works.

  :::

## effectScope() {#effectscope}

Creates an effect scope object which can capture the reactive effects (i.e. computed and watchers) created within it so that these effects can be disposed together. For detailed use cases of this API, please consult its corresponding [RFC](https://github.com/vuejs/rfcs/blob/master/active-rfcs/0041-reactivity-effect-scope.md).

- **Type**

  ```ts
  function effectScope(detached?: boolean): EffectScope

  interface EffectScope {
    run<T>(fn: () => T): T | undefined // undefined if scope is inactive
    stop(): void
  }
  ```

- **Example**

  ```js
  const scope = effectScope()

  scope.run(() => {
    const doubled = computed(() => counter.value * 2)

    watch(doubled, () => console.log(doubled.value))

    watchEffect(() => console.log('Count: ', doubled.value))
  })

  // to dispose all effects in the scope
  scope.stop()
  ```

## getCurrentScope() {#getcurrentscope}

Returns the current active [effect scope](#effectscope) if there is one.

- **Type**

  ```ts
  function getCurrentScope(): EffectScope | undefined
  ```

## onScopeDispose() {#onscopedispose}

Registers a dispose callback on the current active [effect scope](#effectscope). The callback will be invoked when the associated effect scope is stopped.

This method can be used as a non-component-coupled replacement of `onUnmounted` in reusable composition functions, since each Vue component's `setup()` function is also invoked in an effect scope.

A warning will be thrown if this function is called without an active effect scope. In 3.5+, this warning can be suppressed by passing `true` as the second argument.

- **Type**

import { ref } from 'vue'
import { cells, evalCell } from './store.js'

export default {
  props: {
    c: Number,
    r: Number
  },
  setup(props) {
    const editing = ref(false)

    function update(e) {
      editing.value = false
      cells[props.c][props.r] = e.target.value.trim()
    }

    return {
      cells,
      editing,
      evalCell,
      update
    }
  }
}

import { ref, shallowReactive, toRaw } from 'vue'

export default {
  setup() {
    const history = shallowReactive([[]])
    const index = ref(0)
    const circles = ref([])
    const selected = ref()
    const adjusting = ref(false)

    function onClick({ clientX: x, clientY: y }) {
      if (adjusting.value) {
        adjusting.value = false
        selected.value = null
        push()
        return
      }

      selected.value = [...circles.value].reverse().find(({ cx, cy, r }) => {
        const dx = cx - x
        const dy = cy - y
        return Math.sqrt(dx * dx + dy * dy) <= r
      })

      if (!selected.value) {
        circles.value.push({
          cx: x,
          cy: y,
          r: 50
        })
        push()
      }
    }

    function adjust(circle) {
      selected.value = circle
      adjusting.value = true
    }

    function push() {
      history.length = ++index.value
      history.push(clone(circles.value))
      console.log(toRaw(history))
    }

    function undo() {
      circles.value = clone(history[--index.value])
    }

    function redo() {
      circles.value = clone(history[++index.value])
    }

    function clone(circles) {
      return circles.map((c) => ({ ...c }))
    }

    return {
      history,
      index,
      circles,
      selected,
      adjusting,
      onClick,
      adjust,
      undo,
      redo
    }
  }
}

function clone(circles) {
  return circles.map((c) => ({ ...c }))
}

export default {
  data() {
    return {
      history: [[]],
      index: 0,
      circles: [],
      selected: null,
      adjusting: false
    }
  },
  methods: {
    onClick({ clientX: x, clientY: y }) {
      if (this.adjusting) {
        this.adjusting = false
        this.selected = null
        this.push()
        return
      }

      this.selected = [...this.circles].reverse().find(({ cx, cy, r }) => {
        const dx = cx - x
        const dy = cy - y
        return Math.sqrt(dx * dx + dy * dy) <= r
      })

      if (!this.selected) {
        this.circles.push({
          cx: x,
          cy: y,
          r: 50
        })
        this.push()
      }
    },

    adjust(circle) {
      this.selected = circle
      this.adjusting = true
    },

    push() {
      this.history.length = ++this.index
      this.history.push(clone(this.circles))
    },

    undo() {
      this.circles = clone(this.history[--this.index])
    },

    redo() {
      this.circles = clone(this.history[++this.index])
    }
  }
}

import { ref } from 'vue'

export default {
  setup() {
    const show = ref(true)
    const list = ref([1, 2, 3])

    return {
      show,
      list
    }
  }
}

import { ref } from 'vue'

export default {
  setup() {
    // A "ref" is a reactive data source that stores a value.
    // Technically, we don't need to wrap the string with ref()
    // in order to display it, but we will see in the next
    // example why it is needed if we ever intend to change
    // the value.
    const message = ref('Hello World!')

    return {
      message
    }
  }
}

Vue needs to attach event listeners in order to know when a transition has ended. It can either be `transitionend` or `animationend`, depending on the type of CSS rules applied. If you are only using one or the other, Vue can automatically detect the correct type.

However, in some cases you may want to have both on the same element, for example having a CSS animation triggered by Vue, along with a CSS transition effect on hover. In these cases, you will have to explicitly declare the type you want Vue to care about by passing the `type` prop, with a value of either `animation` or `transition`:

```vue-html
<Transition type="animation">...</Transition>
```

### Nested Transitions and Explicit Transition Durations {#nested-transitions-and-explicit-transition-durations}

Although the transition classes are only applied to the direct child element in `<Transition>`, we can transition nested elements using nested CSS selectors:

```vue-html
<Transition name="nested">
  <div v-if="show" class="outer">
    <div class="inner">
      Hello
    </div>
  </div>
</Transition>
```

```css
/* rules that target nested elements */
.nested-enter-active .inner,
.nested-leave-active .inner {
  transition: all 0.3s ease-in-out;
}

.nested-enter-from .inner,
.nested-leave-to .inner {
  transform: translateX(30px);
  opacity: 0;
}

/* ... other necessary CSS omitted */
```

We can even add a transition delay to the nested element on enter, which creates a staggered enter animation sequence:

```css{3}
/* delay enter of nested element for staggered effect */
.nested-enter-active .inner {
  transition-delay: 0.25s;
}
```

However, this creates a small issue. By default, the `<Transition>` component attempts to automatically figure out when the transition has finished by listening to the **first** `transitionend` or `animationend` event on the root transition element. With a nested transition, the desired behavior should be waiting until the transitions of all inner elements have finished.

In such cases you can specify an explicit transition duration (in milliseconds) using the `duration` prop on the `<Transition>` component. The total duration should match the delay plus transition duration of the inner element:

```vue-html
<Transition :duration="550">...</Transition>
```

<NestedTransitions />

[Try it in the Playground](https://play.vuejs.org/#)

If necessary, you can also specify separate values for enter and leave durations using an object:

```vue-html
<Transition :duration="{ enter: 500, leave: 800 }">...</Transition>
```

### Performance Considerations {#performance-considerations}

You may notice that the animations shown above are mostly using properties like `transform` and `opacity`. These properties are efficient to animate because:

1. They do not affect the document layout during the animation, so they do not trigger expensive CSS layout calculation on every animation frame.

2. Most modern browsers can leverage GPU hardware acceleration when animating `transform`.

In comparison, properties like `height` or `margin` will trigger CSS layout, so they are much more expensive to animate, and should be used with caution.

## JavaScript Hooks {#javascript-hooks}

You can hook into the transition process with JavaScript by listening to events on the `<Transition>` component:

```vue-html
<Transition
  @before-enter="onBeforeEnter"
  @enter="onEnter"
  @after-enter="onAfterEnter"
  @enter-cancelled="onEnterCancelled"
  @before-leave="onBeforeLeave"
  @leave="onLeave"
  @after-leave="onAfterLeave"
  @leave-cancelled="onLeaveCancelled"
>
  <!-- ... -->
</Transition>
```

<div class="composition-api">

```js
// called before the element is inserted into the DOM.
// use this to set the "enter-from" state of the element
function onBeforeEnter(el) {}

// called one frame after the element is inserted.
// use this to start the entering animation.
function onEnter(el, done) {
  // call the done callback to indicate transition end
  // optional if used in combination with CSS
  done()
}

// called when the enter transition has finished.
function onAfterEnter(el) {}

// called when the enter transition is cancelled before completion.
function onEnterCancelled(el) {}

// called before the leave hook.
// Most of the time, you should just use the leave hook
function onBeforeLeave(el) {}

// called when the leave transition starts.
// use this to start the leaving animation.
function onLeave(el, done) {
  // call the done callback to indicate transition end
  // optional if used in combination with CSS
  done()
}

// called when the leave transition has finished and the
// element has been removed from the DOM.
function onAfterLeave(el) {}

// only available with v-show transitions
function onLeaveCancelled(el) {}
```

</div>
<div class="options-api">

```js
export default {
  // ...
  methods: {
    // called before the element is inserted into the DOM.
    // use this to set the "enter-from" state of the element
    onBeforeEnter(el) {},

    // called one frame after the element is inserted.
    // use this to start the animation.
    onEnter(el, done) {
      // call the done callback to indicate transition end
      // optional if used in combination with CSS
      done()
    },

    // called when the enter transition has finished.
    onAfterEnter(el) {},

    // called when the enter transition is cancelled before completion.
    onEnterCancelled(el) {},

    // called before the leave hook.
    // Most of the time, you should just use the leave hook.
    onBeforeLeave(el) {},

    // called when the leave transition starts.
    // use this to start the leaving animation.
    onLeave(el, done) {
      // call the done callback to indicate transition end
      // optional if used in combination with CSS
      done()
    },

    // called when the leave transition has finished and the
    // element has been removed from the DOM.
    onAfterLeave(el) {},

    // only available with v-show transitions
    onLeaveCancelled(el) {}
  }
}
```

</div>

These hooks can be used in combination with CSS transitions / animations or on their own.

When using JavaScript-only transitions, it is usually a good idea to add the `:css="false"` prop. This explicitly tells Vue to skip auto CSS transition detection. Aside from being slightly more performant, this also prevents CSS rules from accidentally interfering with the transition:

```vue-html{3}
<Transition
  ...
  :css="false"
>
  ...
</Transition>
```

With `:css="false"`, we are also fully responsible for controlling when the transition ends. In this case, the `done` callbacks are required for the `@enter` and `@leave` hooks. Otherwise, the hooks will be called synchronously and the transition will finish immediately.

